package app.morphe.extension.chmate;
import android.net.Uri;import android.database.Cursor;import android.content.*;import java.util.*;
public class LocalBackupProviderTest {
 static int n;static void check(boolean v,String s){if(!v)throw new AssertionError(s);n++;}
 static class Rows implements Cursor {List<String[]> rows;int i=-1;Rows(List<String[]> r){rows=r;}public boolean moveToNext(){return ++i<rows.size();}public boolean moveToFirst(){i=0;return !rows.isEmpty();}public String getString(int c){return rows.get(i)[c];}public void close(){}}
 static class Store extends ContentResolver {Map<String,String> names=new LinkedHashMap<>();Set<String> moved=new HashSet<>();List<String> deleted=new ArrayList<>();boolean available=true,failDelete;
 public Cursor query(Uri u,String[] p,String s,String[] a,String sort){if(!available)throw new SecurityException();if(u.toString().endsWith("/children")){List<String[]> r=new ArrayList<>();names.forEach((id,name)->r.add(new String[]{id,name}));return new Rows(r);}String id=android.provider.DocumentsContract.getDocumentId(u);return new Rows(names.containsKey(id)||moved.contains(id)?Collections.singletonList(new String[]{id}):Collections.emptyList());}
 public boolean delete(Uri u){deleted.add(u.toString());if(failDelete)return false;names.remove(android.provider.DocumentsContract.getDocumentId(u));return true;}}
 public static void main(String[] args){Store s=new Store();Context c=new Context(){public ContentResolver getContentResolver(){return s;}};Uri tree=Uri.parse("content://provider/tree/folder");List<String> tracked=new ArrayList<>();for(int i=0;i<8;i++){s.names.put("file"+i,"haiagaru-auto-model-"+i+".zip");tracked.add("content://provider/document/file"+i);}s.names.put("manual","manual.zip");s.names.put("untracked","haiagaru-auto-foreign.zip");
 LocalBackupDocuments docs=new LocalBackupDocuments(c,tree);check(docs.inspect(tracked.get(0))==LocalBackupRetention.Presence.OWNED,"plain document URI accepted");check(docs.canonical(tracked.get(0)).equals(docs.canonical("content://provider/tree/folder/document/file0")),"plain and tree aliases canonicalized");var r=LocalBackupRetention.prune(tracked,5,docs);check(r.retained.equals(tracked.subList(3,8)),"keep newest five");check(s.names.size()==7&&s.deleted.size()==3,"actual provider records deleted");check(s.deleted.get(0).contains("/tree/folder/document/"),"delete uses selected tree permission");check(s.names.containsKey("manual")&&s.names.containsKey("untracked"),"manual and untracked backups preserved");
 check(docs.inspect("content://other/document/file3")==LocalBackupRetention.Presence.UNVERIFIED,"other provider excluded");s.moved.add("moved");check(docs.inspect("content://provider/document/moved")==LocalBackupRetention.Presence.UNVERIFIED,"moved document excluded");check(docs.inspect("content://provider/document/missing")==LocalBackupRetention.Presence.MISSING,"deleted record forgotten");check(docs.inspect("content://provider/document/manual")==LocalBackupRetention.Presence.UNVERIFIED,"manual tracked document protected");
 s.available=false;docs=new LocalBackupDocuments(c,tree);check(docs.inspect(tracked.get(3))==LocalBackupRetention.Presence.UNVERIFIED&&!docs.delete(tracked.get(3)),"permission failure prevents deletion");s.available=true;s.failDelete=true;docs=new LocalBackupDocuments(c,tree);r=LocalBackupRetention.prune(tracked.subList(3,8),3,docs);check(r.unresolved==2&&r.retained.size()==5,"failed deletion recorded and newer backups retained");s.failDelete=false;docs=new LocalBackupDocuments(c,tree);List<String> aliases=List.of(docs.canonical("content://provider/document/file7"),docs.canonical("content://provider/tree/folder/document/file6"),docs.canonical("content://provider/tree/folder/document/file7"));r=LocalBackupRetention.prune(aliases,2,docs);check(r.retained.size()==2&&s.names.containsKey("file7"),"duplicate aliases never delete protected newest file");System.out.println("PASS "+n+" document-provider retention checks");}}
